package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** A person's statements as shown: how many were taken, and the last one's due-total and date (null with none). */
public record Statements(int count, BigDecimal lastDueTotal, LocalDate lastDate) {

    public static final Statements NONE = new Statements(0, null, null);

    /** A person's statements, in the order taken. */
    public static Statements of(List<Statement> taken) {
        if (taken.isEmpty()) {
            return NONE;
        }
        Statement last = taken.get(taken.size() - 1);
        return new Statements(taken.size(), last.getDueTotal(), last.getTakenOn());
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rate.RateTable;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The statements taken for the people on a sheet. Taking one records the person's due-total and
 * binds each of their claims that counts to the figure it has then (without its late charge, which
 * keeps following the sheet's today); a claim that does not count is released to its live figure. A
 * statement can be taken as of a date gone by, from the sheet as it stood at the end of that date.
 * A steward can cancel a person's last statement: the claims it bound are released to their live
 * figures (a figure an earlier statement bound is not restored).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateService rates;
    private final Rollup rollup;
    private final AccessService access;
    private final DayEnds dayEnds;
    private final ApplicationEventPublisher events;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            RateService rates, Rollup rollup, AccessService access, DayEnds dayEnds,
            ApplicationEventPublisher events) {
        this.dayEnds = dayEnds;
        this.access = access;
        this.rollup = rollup;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.events = events;
    }

    /** Every person's statements on the sheet, by person. */
    @Transactional(readOnly = true)
    public Map<Long, Statements> bySheet(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId,
                        Collectors.collectingAndThen(Collectors.toList(), Statements::of)));
    }

    @Transactional(readOnly = true)
    public Statements forPerson(String sheetId, long personId) {
        return Statements.of(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
    }

    /** Take a statement for the person as of the sheet's today. */
    @Transactional
    public void take(String sheetId, String user, long personId) {
        take(sheetId, user, personId, null);
    }

    /**
     * Take a statement for the person as of a date on or before the sheet's today (null: as of now). Their
     * claims that counted at the end of that date are bound to the figures they had then, with that date
     * standing in for the sheet's today, and every other claim of theirs is released; the statement is
     * dated that date and records their due-total then. A date gone by takes the sheet as it stood at the
     * end of it (see {@link DayEnds}): refused when the date is after the sheet's today, or when the person
     * was not on the sheet by then.
     */
    @Transactional
    public void take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RateTable table = rates.table(sheetId);
        LocalDate on = asOf == null ? table.today() : asOf;
        if (on.isAfter(table.today())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A statement cannot be taken as of a date after today");
        }
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        Person then;
        Map<Long, Claim> claimsThen;
        if (on.isBefore(table.today())) {
            DayEnds.SheetThen sheetThen = dayEnds.asOf(sheetId, on)
                    .filter(t -> t.people().containsKey(personId))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
                            "The person was not on the sheet by that date"));
            then = sheetThen.people().get(personId);
            claimsThen = sheetThen.claimsOf(personId);
            table = sheetThen.table();
        } else {
            then = person;
            claimsThen = new LinkedHashMap<>();
            theirs.forEach(c -> claimsThen.put(c.getId(), c));
        }
        Rollup.Figures before = rollup.figures(sheetId);
        BigDecimal dueTotal = Dues.total(then::gradeOn, List.copyOf(claimsThen.values()), table, then.leaves());
        int counting = 0;
        for (Claim claim : theirs) {
            Claim stood = claimsThen.get(claim.getId());
            if (stood != null && Dues.counts(stood, then.leaves(), table.today())) {
                claim.bind(Dues.base(stood, then::gradeOn, table));
                counting++;
            } else {
                claim.unbind();
            }
        }
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, on, dueTotal, counting));
        events.publishEvent(new StatementTaken(sheetId, user, person.getName(), dueTotal, counting, asOf));
        rollup.changed(sheetId, user, before);
    }

    /**
     * Carry a person's statements to the person receiving them in a merge or transfer: the receiver's count
     * becomes their own plus the other's, and the receiver's last statement stays theirs (or, having none,
     * becomes the other's). The other's statements are dropped from them.
     */
    @Transactional
    public void carry(String fromSheet, long fromPerson, String toSheet, long toPerson) {
        List<Statement> theirs = statements.findBySheetIdAndPersonIdOrderByIdAsc(fromSheet, fromPerson);
        List<Statement> own = statements.findBySheetIdAndPersonIdOrderByIdAsc(toSheet, toPerson);
        // taken in order by id: the other's come first, then the receiver's own taken again after them
        List<Statement> carried = new ArrayList<>();
        theirs.forEach(s -> carried.add(s.carried(toSheet, toPerson)));
        own.forEach(s -> carried.add(s.carried(toSheet, toPerson)));
        statements.deleteAll(theirs);
        statements.deleteAll(own);
        statements.flush();
        statements.saveAllAndFlush(carried);
    }

    /** Cancel the person's last statement; only a steward may, and only while the person has one. */
    @Transactional
    public void cancel(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
        }
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (taken.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Statement last = taken.get(taken.size() - 1);
        for (Claim claim : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (claim.isStated()) {
                claim.unbind();
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        events.publishEvent(new StatementCancelled(sheetId, user, person.getName(), last.getDueTotal()));
        rollup.changed(sheetId, user, before);
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);
}
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then and its due then (null when none). */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {

        static LogLineView of(ClaimLogLine line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(), money(line.getDue()));
        }
    }

    /**
     * A person with the grade in force on the sheet's today, their own terms (null: none), their claims, newest first, claimed: the sum of the amounts of the claims that
     * count, leaving out corrections (OPEN, PENDING and SETTLED, but not an unbound OPEN claim dated within a hold, see {@link Dues#counts}), dueTotal: the sum of the due figures of the claims that count (see
     * {@link Dues#total}, held to the sheet's cap), excess: what the sum is above the cap (0.00 when it is not), and their statements: how many were taken, the last one's due-total (null when
     * there is none or it was n/a) and date (null when there is none), whether they are retired and
     * the date they are retired from (null when not), whether they have any hold and their holds, and how many of the claims
     * that count are overdue and the sum of their due figures, the ids of their patrons, and whether they are
     * active (see {@link Dues#active}), and recentSettled: their recent settled figures (see {@link Dues#recentSettled}), and retiredNow: whether
     * the sheet's today has reached their retirement date (their unbound OPEN and PENDING claims then count in no live total),
     * and aged0to30, aged31to60 and aged61: the due of their OPEN and PENDING claims that count by the claim's age on the
     * sheet's today (see {@link Dues#aged}), and settledTotal and openTotal: the parts of their uncapped due-total
     * from their SETTLED claims and from their OPEN and PENDING claims (see {@link Dues#settledTotal} and
     * {@link Dues#openTotal}; 0.00 with none, never n/a), and their aliases, sorted as names are compared, and clashing: whether their name or an alias is
     * another's on a sheet of the sheet's tree (see {@link PersonService#clashing}), and the sheet they were
     * transferred from (null: none), their past retirements, earliest first, and their snapshot lines, oldest first.
     */
    public record PersonView(long id, long version, String name, String grade, Integer terms, String contact,
            List<String> tags,
            List<ClaimView> claims,
            String claimed, String dueTotal, String excess, int statementCount, String statedTotal, LocalDate statementDate,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, int overdueCount,
            String overdueTotal, List<Long> patrons, boolean active, String recentSettled, boolean retiredNow,
            String aged0to30, String aged31to60, String aged61, String settledTotal, String openTotal,
            List<String> aliases, boolean clashing, String origin, List<RetirementView> retirements,
            List<SnapshotView> snapshots) {

        /** The person as shown, given the sheet's rates and whether they clash (see {@link PersonService#clashing}). */
        public static PersonView of(Person person, List<Claim> claims, RateTable rates, Statements statements,
                List<Long> patrons, boolean clashing, List<PersonSnapshot> snapshots) {
            Grades grade = person::gradeOn;
            Holds held = person.leaves();
            BigDecimal claimed = Dues.claimed(claims, held, rates.today());
            List<Claim> overdue = Dues.overdue(claims, grade, rates, held);
            return new PersonView(person.getId(), person.getVersion(), person.getName(),
                    grade.on(rates.today()), person.getTerms(), person.getContact(), Tags.list(person.getTags()), claims.stream().map(c -> ClaimView.of(c, grade, rates, held)).toList(), money(claimed),
                    money(Dues.total(grade, claims, rates, held)), money(Dues.excess(grade, claims, rates, held)),
                    statements.count(),
                    money(statements.lastDueTotal()), statements.lastDate(), person.isRetired(),
                    person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    overdue.size(), money(Dues.sum(grade, overdue, rates)),
                    patrons, Dues.active(claims, held, rates.today()),
                    money(Dues.recentSettled(claims, rates.today())), person.retiredOn(rates.today()),
                    money(Dues.aged(grade, claims, rates, held, 0, 30)),
                    money(Dues.aged(grade, claims, rates, held, 31, 60)),
                    money(Dues.aged(grade, claims, rates, held, 61, Long.MAX_VALUE)),
                    money(Dues.settledTotal(grade, claims, rates, held)),
                    money(Dues.openTotal(grade, claims, rates, held)), person.getAliases(), clashing,
                    person.getOrigin(), person.getRetirements().stream()
                            .map(r -> new RetirementView(r.getFromDate(), r.getToDate())).toList(),
                    snapshots.stream().map(s -> new SnapshotView(s.getDay(), s.getDueTotal())).toList());
        }
    }

    /** A past retirement of a person: from the date they were retired from to the day they were unretired. */
    public record RetirementView(LocalDate from, LocalDate to) {
    }

    /** A snapshot line of a person: the day being left and their due-total on it as shown ('n/a': none). */
    public record SnapshotView(LocalDate day, String dueTotal) {
    }

    /** A hold on a person: from a date to a date (null: open-ended). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    private static String money(BigDecimal amount) {
        return amount == null ? null : amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }

    /**
     * A person as entered; an edit carries the version its editor loaded (none: no check) and the date
     * its grade applies from (none: the sheet's today). An add's grade applies from the beginning of time.
     * The person's own terms are a number of days, blank (or none) for none; their contact a text, blank
     * (or none) for none; their tags comma separated text (none: none on an add, as they were on an edit).
     */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, Long version, LocalDate gradeFrom,
            @Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String terms, @Size(max = 200) String contact,
            @Size(max = 1000) String tags) {

        /** The contact trimmed and lower-cased; null when there is none. */
        String contactKey() {
            return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(Locale.ROOT);
        }

        /** The terms as days; null when there are none. */
        Integer termsDays() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }
    }

    /** A retirement as entered; a date left out takes the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** A grade for the selected people as entered: from a date (none: the sheet's today). */
    public record BulkGradeForm(@NotEmpty List<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate from) {
    }

    /** A retirement for the selected people as entered: from a date (none: the sheet's today). */
    public record BulkRetireForm(@NotEmpty List<@NotNull Long> personIds, LocalDate from) {
    }

    /** Pasted lines of name,grade,terms,contact, one person per line; terms and contact may be left out. */
    public record ImportForm(@NotNull @Size(max = 100_000) String text) {
    }

    private final PersonService service;
    private final PersonImportService imports;
    private final BulkGradeService bulkGrade;
    private final BulkRetireService bulkRetire;
    private final ClaimService claims;
    private final RateService rates;
    private final StatementService statements;
    private final PersonMergeService merges;
    private final PersonTransferService transfers;

    public PersonController(PersonService service, BulkGradeService bulkGrade, ClaimService claims,
            RateService rates, StatementService statements, PersonMergeService merges,
            PersonTransferService transfers, PersonImportService imports, BulkRetireService bulkRetire) {
        this.bulkRetire = bulkRetire;
        this.service = service;
        this.imports = imports;
        this.transfers = transfers;
        this.merges = merges;
        this.bulkGrade = bulkGrade;
        this.claims = claims;
        this.rates = rates;
        this.statements = statements;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        Map<Long, List<Claim>> bySheet = claims.bySheet(sheet);
        RateTable table = rates.table(sheet);
        Map<Long, Statements> stated = statements.bySheet(sheet);
        Map<Long, List<Long>> patrons = service.patronsBySheet(sheet);
        Set<Long> clashing = service.clashing(sheet);
        Map<Long, List<PersonSnapshot>> snapshots = service.snapshotsBySheet(sheet);
        return service.list(sheet).stream()
                .map(p -> PersonView.of(p, bySheet.getOrDefault(p.getId(), List.of()), table,
                        stated.getOrDefault(p.getId(), Statements.NONE),
                        patrons.getOrDefault(p.getId(), List.of()), clashing.contains(p.getId()),
                        snapshots.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** The people of the sheet's tree whose name or an alias contains the text (see {@link PersonService#search}). */
    @GetMapping("/search")
    public List<PersonService.Found> search(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return service.search(sheetId.trim(), text);
    }

    @PostMapping
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody PersonForm form) {
        String sheet = sheetId.trim();
        return PersonView.of(service.add(sheet, user.trim(), form.name(), form.grade(), form.termsDays(),
                form.contactKey(), form.tags()), List.of(),
                rates.table(sheet), Statements.NONE, List.of(), false, List.of());
    }

    /** Update or add a person per pasted line, in order; one refused line imports none. */
    @PostMapping("/import")
    public PersonImportService.Result importPeople(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody ImportForm form) {
        return imports.importPeople(sheetId.trim(), user.trim(), form.text());
    }

